contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address account, uint256 id) public {
        uint256 beforeBalance = account == address(0) ? 0 : c.balanceOf(account, id);
        uint256 beforeSupplyOfAccountId = beforeBalance;

        bool reverted;
        uint256 returned;
        try c.balanceOf(account, id) returns (uint256 b) {
            reverted = false;
            returned = b;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = account == address(0) ? 0 : c.balanceOf(account, id);

        assert(reverted == (account == address(0)));
        assert(afterBalance == beforeSupplyOfAccountId);
    }
}
